# Level 2: Analysis 1 (Kanon: Forster Analysis 1, Königsberger Analysis 1)
L2 = []
def c(typ, topic, name, back, front="", extra=""):
    L2.append(dict(type=typ, topic=topic, name=name, front=front, back=back, extra=extra, flag=""))

T="Grundlagen"
c("Satz",T,r"Prinzip der vollständigen Induktion",r"Sei $A(n)$ eine Aussage für $n\in\mathbb N$. Gilt $A(1)$ (Induktionsanfang) und folgt für jedes $n$ aus $A(n)$ die Aussage $A(n+1)$ (Induktionsschritt), so gilt $A(n)$ für alle $n\in\mathbb N$.")
c("Satz",T,r"Dreiecksungleichung in $\mathbb R$",r"$|x+y|\le|x|+|y|$ und $\big||x|-|y|\big|\le|x-y|$ für alle $x,y\in\mathbb R$.")
c("Satz",T,r"Ungleichung vom arithmetischen und geometrischen Mittel",r"Für $x_1,\dots,x_n\ge0$ gilt $\sqrt[n]{x_1\cdots x_n}\le\dfrac{x_1+\dots+x_n}n$, mit Gleichheit genau dann, wenn alle $x_i$ gleich sind.")
c("Satz",T,r"Cauchy-Schwarz-Ungleichung",r"Für $x,y\in\mathbb R^n$: $\displaystyle\Big|\sum_{i=1}^n x_iy_i\Big|\le\Big(\sum x_i^2\Big)^{1/2}\Big(\sum y_i^2\Big)^{1/2}$, also $|\langle x,y\rangle|\le\|x\|\,\|y\|$.")
c("Satz",T,r"Überabzählbarkeit von $\mathbb R$",r"$\mathbb R$ ist nicht abzählbar.",extra=r"Beweis: Cantors Diagonalargument oder Intervallschachtelung, die jedes $x_n$ einer Abzählung ausschließt.")
c("Satz",T,r"Existenz der $k$-ten Wurzel",r"Zu jedem $a\ge0$ und $k\in\mathbb N$ gibt es genau ein $x\ge0$ mit $x^k=a$.",extra=r"Beweis: $x=\sup\{t\ge0: t^k\le a\}$ oder über das Heron-Verfahren.")

T="Folgen"
c("Definition",T,r"Limes superior / inferior",r"Für eine beschränkte reelle Folge: $\limsup_{n\to\infty}x_n := \lim_{n\to\infty}\sup_{k\ge n}x_k$, $\liminf_{n\to\infty} x_n := \lim_{n\to\infty}\inf_{k\ge n}x_k$. Gleichwertig: größter bzw. kleinster Häufungswert.")
c("Definition",T,r"Häufungswert (Häufungspunkt) einer Folge",r"$a$ heißt Häufungswert von $(x_n)$, wenn es eine Teilfolge gibt, die gegen $a$ konvergiert (gleichwertig: in jeder $\varepsilon$-Umgebung von $a$ liegen unendlich viele Folgenglieder).")
c("Satz",T,r"",r"$(x_n)$ konvergiert genau dann, wenn $\limsup x_n=\liminf x_n$. Dann ist dieser Wert der Grenzwert.",front=r"Sei $(x_n)$ beschränkte reelle Folge. Wann konvergiert sie (Kriterium mit lim sup/lim inf)?")
c("Satz",T,r"Cauchy-Kriterium für Folgen in $\mathbb R$",r"Eine reelle Folge konvergiert genau dann, wenn sie eine Cauchy-Folge ist. ($\mathbb R$ ist vollständig.)")
c("Satz",T,r"Eulersche Zahl als Grenzwert",r"Die Folge $\left(1+\tfrac1n\right)^n$ ist monoton wachsend und beschränkt; ihr Grenzwert ist $e=\displaystyle\sum_{k=0}^\infty\frac1{k!}\approx2{,}71828$.")
c("Satz",T,r"Wichtige Grenzwerte",r"$\sqrt[n]n\to1$, $\sqrt[n]a\to1$ ($a>0$), $q^n\to0$ für $|q|<1$, $\dfrac{n^k}{z^n}\to0$ für $|z|>1$, $\dfrac{z^n}{n!}\to0$.")

T="Reihen"
c("Definition",T,r"Reihe und Konvergenz einer Reihe",r"Zu einer Folge $(a_k)$ heißt die Folge der Partialsummen $s_n=\sum_{k=1}^n a_k$ Reihe $\sum a_k$. Die Reihe konvergiert, wenn $(s_n)$ konvergiert; ihr Wert ist $\sum_{k=1}^\infty a_k:=\lim s_n$.")
c("Satz",T,r"Notwendiges Kriterium (Trivialkriterium)",r"Konvergiert $\sum a_k$, so ist $(a_k)$ eine Nullfolge.",extra=r"Nicht hinreichend: Die harmonische Reihe $\sum\frac1k$ divergiert, obwohl $\frac1k\to0$.")
c("Satz",T,r"Geometrische Reihe",r"Für $|q|<1$ gilt $\displaystyle\sum_{k=0}^\infty q^k=\frac1{1-q}$. Für $|q|\ge1$ divergiert die Reihe.")
c("Satz",T,r"Divergenz der harmonischen Reihe",r"$\displaystyle\sum_{k=1}^\infty\frac1k=\infty$. Dagegen konvergiert $\sum\frac1{k^s}$ für $s>1$.",extra=r"Beweis: Blöcke $\frac1{2^m+1}+\dots+\frac1{2^{m+1}}\ge\frac12$.")
c("Satz",T,r"Cauchy-Kriterium für Reihen",r"$\sum a_k$ konvergiert genau dann, wenn $\forall\varepsilon>0\ \exists N\ \forall n>m\ge N: \Big|\sum_{k=m+1}^n a_k\Big|<\varepsilon$.")
c("Satz",T,r"Leibniz-Kriterium",r"Ist $(a_k)$ eine monoton fallende Nullfolge nichtnegativer Zahlen, so konvergiert die alternierende Reihe $\sum_{k}(-1)^k a_k$.",extra=r"Fehlerabschätzung: $|s-s_n|\le a_{n+1}$. Beispiel: $\sum\frac{(-1)^{k+1}}k=\ln2$.")
c("Definition",T,r"Absolute Konvergenz",r"$\sum a_k$ heißt absolut konvergent, wenn $\sum|a_k|$ konvergiert.",extra=r"Absolut konvergent $\Rightarrow$ konvergent. Umkehrung falsch: alternierende harmonische Reihe.")
c("Satz",T,r"Majorantenkriterium",r"Ist $|a_k|\le b_k$ für fast alle $k$ und konvergiert $\sum b_k$, so konvergiert $\sum a_k$ absolut. (Minorantenkriterium: $0\le b_k\le a_k$ und $\sum b_k$ divergent $\Rightarrow\sum a_k$ divergent.)")
c("Satz",T,r"Quotientenkriterium",r"Gibt es $0<q<1$ mit $a_k\ne0$ und $\left|\dfrac{a_{k+1}}{a_k}\right|\le q$ für fast alle $k$, so konvergiert $\sum a_k$ absolut. Gilt $\left|\frac{a_{k+1}}{a_k}\right|\ge1$ für fast alle $k$, divergiert sie.",extra=r"Achtung: $\left|\frac{a_{k+1}}{a_k}\right|<1$ allein reicht nicht (harmonische Reihe).")
c("Satz",T,r"Wurzelkriterium",r"Ist $\limsup\sqrt[k]{|a_k|}<1$, so konvergiert $\sum a_k$ absolut; ist $\limsup\sqrt[k]{|a_k|}>1$, divergiert sie.")
c("Satz",T,r"Cauchy-Verdichtungskriterium",r"Ist $(a_k)$ monoton fallend mit $a_k\ge0$, so konvergiert $\sum a_k$ genau dann, wenn $\sum 2^k a_{2^k}$ konvergiert.")
c("Satz",T,r"Umordnungssatz",r"Ist $\sum a_k$ absolut konvergent, so konvergiert jede Umordnung $\sum a_{\sigma(k)}$ (absolut) gegen denselben Wert.")
c("Satz",T,r"Riemannscher Umordnungssatz",r"Ist $\sum a_k$ konvergent, aber nicht absolut konvergent (reell), so gibt es zu jedem $s\in\mathbb R\cup\{\pm\infty\}$ eine Umordnung mit Summe $s$.")
c("Satz",T,r"Cauchy-Produkt",r"Sind $\sum a_k$ und $\sum b_k$ absolut konvergent, so konvergiert $\displaystyle\sum_{n=0}^\infty c_n$ mit $c_n=\sum_{k=0}^n a_kb_{n-k}$ absolut, und $\sum c_n=\big(\sum a_k\big)\big(\sum b_k\big)$.")

T="Stetigkeit"
c("Definition",T,r"Grenzwert einer Funktion",r"Sei $D\subseteq\mathbb R$, $a$ Häufungspunkt von $D$. $\lim_{x\to a}f(x)=c$, wenn für jede Folge $(x_n)$ in $D\setminus\{a\}$ mit $x_n\to a$ gilt $f(x_n)\to c$. Gleichwertig: $\forall\varepsilon\ \exists\delta: 0<|x-a|<\delta\Rightarrow|f(x)-c|<\varepsilon$.")
c("Definition",T,r"Stetigkeit ($\varepsilon$-$\delta$)",r"$f:D\to\mathbb R$ heißt stetig in $a\in D$, wenn $$\forall\varepsilon>0\ \exists\delta>0\ \forall x\in D: |x-a|<\delta\Rightarrow|f(x)-f(a)|<\varepsilon.$$")
c("Satz",T,r"Folgenkriterium der Stetigkeit",r"$f$ ist stetig in $a$ genau dann, wenn für jede Folge $x_n\to a$ in $D$ gilt $f(x_n)\to f(a)$.",extra=r"Nützlich für Unstetigkeitsbeweise: eine Folge finden, für die $f(x_n)\not\to f(a)$.")
c("Satz",T,r"Zwischenwertsatz",r"Ist $f:[a,b]\to\mathbb R$ stetig und $y$ zwischen $f(a)$ und $f(b)$, so gibt es ein $\xi\in[a,b]$ mit $f(\xi)=y$.",extra=r"Beweis: Bisektion (Intervallschachtelung). Speziell (Nullstellensatz von Bolzano): $f(a)<0<f(b)\Rightarrow$ Nullstelle.")
c("Satz",T,r"Satz vom Maximum und Minimum (Extremwertsatz)",r"Jede stetige Funktion $f:[a,b]\to\mathbb R$ auf einem kompakten Intervall ist beschränkt und nimmt Maximum und Minimum an.",extra=r"Gegenbeispiel auf offenem Intervall: $f(x)=1/x$ auf $(0,1]$.")
c("Definition",T,r"Gleichmäßige Stetigkeit",r"$f:D\to\mathbb R$ heißt gleichmäßig stetig, wenn $\forall\varepsilon>0\ \exists\delta>0\ \forall x,y\in D: |x-y|<\delta\Rightarrow|f(x)-f(y)|<\varepsilon$ ($\delta$ hängt nicht von der Stelle ab).",extra=r"$x\mapsto x^2$ ist auf $\mathbb R$ stetig, aber nicht gleichmäßig stetig.")
c("Satz",T,r"Satz von Heine",r"Jede stetige Funktion auf einem kompakten Intervall $[a,b]$ ist gleichmäßig stetig.")
c("Definition",T,r"Lipschitz-Stetigkeit",r"$f$ heißt Lipschitz-stetig mit Konstante $L\ge0$, wenn $|f(x)-f(y)|\le L|x-y|$ für alle $x,y\in D$.",extra=r"Lipschitz $\Rightarrow$ gleichmäßig stetig $\Rightarrow$ stetig. $\sqrt x$ auf $[0,1]$ ist gleichmäßig stetig, aber nicht Lipschitz.")
c("Satz",T,r"Stetigkeit der Umkehrfunktion",r"Ist $I$ ein Intervall und $f:I\to\mathbb R$ stetig und streng monoton, so ist $f(I)$ ein Intervall und $f^{-1}:f(I)\to I$ stetig und streng monoton.")
c("Satz",T,r"",r"Summen, Produkte, Quotienten (wo Nenner $\ne0$) und Kompositionen stetiger Funktionen sind stetig.",front=r"Seien $f,g$ stetig. Was gilt für $f+g$, $f\cdot g$, $f/g$, $g\circ f$?")

T="Elementare Funktionen"
c("Definition",T,r"Exponentialfunktion",r"$\displaystyle\exp(z):=\sum_{k=0}^\infty\frac{z^k}{k!}$ für $z\in\mathbb C$ (absolut konvergent für alle $z$).")
c("Satz",T,r"Funktionalgleichung der Exponentialfunktion",r"$\exp(z+w)=\exp(z)\exp(w)$ für alle $z,w\in\mathbb C$.",extra=r"Beweis: Cauchy-Produkt und binomischer Satz. Folgerung: $\exp(x)>0$ und $\exp(-x)=1/\exp(x)$.")
c("Definition",T,r"Natürlicher Logarithmus",r"$\ln:(0,\infty)\to\mathbb R$ ist die Umkehrfunktion von $\exp:\mathbb R\to(0,\infty)$. Es gilt $\ln(xy)=\ln x+\ln y$.")
c("Definition",T,r"Allgemeine Potenz",r"Für $a>0$, $x\in\mathbb R$: $a^x:=\exp(x\ln a)$.")
c("Definition",T,r"Sinus und Kosinus (Reihen)",r"$\displaystyle\cos x=\sum_{k=0}^\infty\frac{(-1)^kx^{2k}}{(2k)!},\quad \sin x=\sum_{k=0}^\infty\frac{(-1)^kx^{2k+1}}{(2k+1)!}$")
c("Satz",T,r"Eulersche Formel",r"$e^{ix}=\cos x+i\sin x$ für $x\in\mathbb R$. Insbesondere $\cos x=\operatorname{Re}e^{ix}$, $\sin x=\operatorname{Im}e^{ix}$ und $e^{i\pi}=-1$.")
c("Satz",T,r"Additionstheoreme",r"$\cos(x+y)=\cos x\cos y-\sin x\sin y$, $\sin(x+y)=\sin x\cos y+\cos x\sin y$. Zudem $\sin^2x+\cos^2x=1$.")
c("Definition",T,r"Die Zahl $\pi$",r"$\pi/2$ ist die (eindeutige) kleinste positive Nullstelle des Kosinus im Intervall $[0,2]$.")

T="Differentiation"
c("Definition",T,r"Differenzierbarkeit",r"$f:I\to\mathbb R$ heißt in $a\in I$ differenzierbar, wenn $f'(a):=\displaystyle\lim_{h\to0}\frac{f(a+h)-f(a)}h$ existiert. Gleichwertig: $f(a+h)=f(a)+f'(a)h+r(h)$ mit $r(h)/h\to0$.")
c("Satz",T,r"",r"$f$ ist stetig in $a$.",front=r"Sei $f$ differenzierbar in $a$.",extra=r"Umkehrung falsch: $|x|$ ist in $0$ stetig, aber nicht differenzierbar.")
c("Satz",T,r"Produktregel und Quotientenregel",r"$(fg)'=f'g+fg'$, $\left(\dfrac fg\right)'=\dfrac{f'g-fg'}{g^2}$ (wo $g\ne0$).")
c("Satz",T,r"Kettenregel",r"Ist $f$ in $a$ und $g$ in $f(a)$ differenzierbar, so ist $g\circ f$ in $a$ differenzierbar mit $(g\circ f)'(a)=g'(f(a))\,f'(a)$.")
c("Satz",T,r"Ableitung der Umkehrfunktion",r"Ist $f$ streng monoton, stetig, in $a$ differenzierbar mit $f'(a)\ne0$, so ist $f^{-1}$ in $b=f(a)$ differenzierbar mit $(f^{-1})'(b)=\dfrac1{f'(f^{-1}(b))}$.")
c("Satz",T,r"Notwendige Bedingung für lokale Extrema",r"Hat $f$ in einem inneren Punkt $a$ ein lokales Extremum und ist dort differenzierbar, so gilt $f'(a)=0$.",extra=r"Nicht hinreichend: $f(x)=x^3$ in $0$.")
c("Satz",T,r"Satz von Rolle",r"Ist $f:[a,b]\to\mathbb R$ stetig, auf $(a,b)$ differenzierbar und $f(a)=f(b)$, so gibt es $\xi\in(a,b)$ mit $f'(\xi)=0$.")
c("Satz",T,r"Mittelwertsatz der Differentialrechnung",r"Ist $f:[a,b]\to\mathbb R$ stetig und auf $(a,b)$ differenzierbar, so gibt es $\xi\in(a,b)$ mit $$f'(\xi)=\frac{f(b)-f(a)}{b-a}.$$")
c("Satz",T,r"Verallgemeinerter Mittelwertsatz",r"Sind $f,g$ stetig auf $[a,b]$, differenzierbar auf $(a,b)$, so gibt es $\xi\in(a,b)$ mit $(f(b)-f(a))g'(\xi)=(g(b)-g(a))f'(\xi)$.")
c("Korollar",T,r"",r"$f$ ist auf $I$ monoton wachsend ($f'\ge0$), streng monoton wachsend ($f'>0$) bzw. konstant ($f'=0$).",front=r"Sei $f$ auf einem Intervall $I$ differenzierbar mit $f'\ge0$ (bzw. $f'>0$, bzw. $f'=0$).",extra=r"Folgt aus dem Mittelwertsatz. $f'>0$ ist nicht notwendig für strenge Monotonie: $x^3$.")
c("Satz",T,r"Regel von de l'Hospital",r"Seien $f,g$ auf $(a,b)$ differenzierbar, $g'\ne0$, und $f,g\to0$ (oder $|g|\to\infty$) für $x\to a$. Existiert $\lim_{x\to a}\frac{f'(x)}{g'(x)}=c$, so gilt $\lim_{x\to a}\frac{f(x)}{g(x)}=c$.")
c("Satz",T,r"Hinreichende Bedingung für lokale Extrema",r"Ist $f$ zweimal differenzierbar, $f'(a)=0$ und $f''(a)>0$ ($<0$), so hat $f$ in $a$ ein strenges lokales Minimum (Maximum).")
c("Definition",T,r"Konvexe Funktion",r"$f:I\to\mathbb R$ heißt konvex, wenn $f(\lambda x+(1-\lambda)y)\le\lambda f(x)+(1-\lambda)f(y)$ für alle $x,y\in I$, $\lambda\in[0,1]$.",extra=r"Für zweimal differenzierbares $f$: konvex $\Leftrightarrow f''\ge0$.")
c("Satz",T,r"Satz von Taylor (Lagrange-Restglied)",r"Ist $f$ auf $I$ $(n+1)$-mal differenzierbar, $a,x\in I$, so gibt es $\xi$ zwischen $a$ und $x$ mit $$f(x)=\sum_{k=0}^n\frac{f^{(k)}(a)}{k!}(x-a)^k+\frac{f^{(n+1)}(\xi)}{(n+1)!}(x-a)^{n+1}.$$")
c("Definition",T,r"Taylorreihe",r"Ist $f$ beliebig oft differenzierbar, so heißt $\displaystyle\sum_{k=0}^\infty\frac{f^{(k)}(a)}{k!}(x-a)^k$ Taylorreihe von $f$ in $a$.",extra=r"Gegenbeispiel: $f(x)=e^{-1/x^2}$, $f(0)=0$ hat Taylorreihe $0$ in $0$, stimmt aber nur dort mit $f$ überein.")

T="Integration"
c("Definition",T,r"Treppenfunktion",r"$\varphi:[a,b]\to\mathbb R$ heißt Treppenfunktion, wenn es eine Zerlegung $a=x_0<\dots<x_n=b$ gibt, sodass $\varphi$ auf jedem $(x_{k-1},x_k)$ konstant $=c_k$ ist. $\int_a^b\varphi:=\sum c_k(x_k-x_{k-1})$.")
c("Definition",T,r"Riemann-Integrierbarkeit",r"$f:[a,b]\to\mathbb R$ beschränkt heißt Riemann-integrierbar, wenn Ober- und Unterintegral übereinstimmen: $$\inf\Big\{\int\varphi:\varphi\ge f\Big\}=\sup\Big\{\int\psi:\psi\le f\Big\}$$ ($\varphi,\psi$ Treppenfunktionen). Der gemeinsame Wert ist $\int_a^bf(x)\,dx$.",extra=r"Gleichwertig über Riemann-Summen oder Ober- und Untersummen. Die Dirichlet-Funktion $\mathbf 1_{\mathbb Q}$ ist nicht Riemann-integrierbar.")
c("Satz",T,r"",r"$f$ ist Riemann-integrierbar.",front=r"Sei $f:[a,b]\to\mathbb R$ stetig oder monoton.",extra=r"Beweis für stetige $f$: gleichmäßige Stetigkeit (Satz von Heine).")
c("Satz",T,r"Monotonie und Linearität des Integrals",r"$\int(\alpha f+\beta g)=\alpha\int f+\beta\int g$; aus $f\le g$ folgt $\int f\le\int g$; außerdem $\left|\int f\right|\le\int|f|$.")
c("Satz",T,r"Mittelwertsatz der Integralrechnung",r"Ist $f:[a,b]\to\mathbb R$ stetig und $g\ge0$ integrierbar, so gibt es $\xi\in[a,b]$ mit $\int_a^bf g=f(\xi)\int_a^bg$. Speziell: $\int_a^bf=f(\xi)(b-a)$.")
c("Satz",T,r"Hauptsatz der Differential- und Integralrechnung",r"Sei $f:I\to\mathbb R$ stetig, $a\in I$. Dann ist $F(x)=\int_a^xf(t)\,dt$ differenzierbar mit $F'=f$. Ist $G$ irgendeine Stammfunktion von $f$, so gilt $\int_a^bf=G(b)-G(a)$.")
c("Satz",T,r"Partielle Integration",r"$\displaystyle\int_a^bf'g=\big[fg\big]_a^b-\int_a^bfg'$ für stetig differenzierbare $f,g$.")
c("Satz",T,r"Substitutionsregel",r"Ist $f$ stetig und $\varphi:[a,b]\to I$ stetig differenzierbar, so gilt $\displaystyle\int_a^bf(\varphi(t))\varphi'(t)\,dt=\int_{\varphi(a)}^{\varphi(b)}f(x)\,dx$.")
c("Definition",T,r"Uneigentliches Integral",r"$\displaystyle\int_a^\infty f:=\lim_{R\to\infty}\int_a^Rf$, falls $f$ auf jedem $[a,R]$ integrierbar ist und der Grenzwert existiert; analog bei Singularitäten am Rand.",extra=r"$\int_1^\infty x^{-s}dx$ konvergiert genau für $s>1$, $\int_0^1x^{-s}dx$ genau für $s<1$.")
c("Satz",T,r"Integralvergleichskriterium",r"Ist $f:[1,\infty)\to[0,\infty)$ monoton fallend, so konvergiert $\sum_{n=1}^\infty f(n)$ genau dann, wenn $\int_1^\infty f(x)\,dx$ konvergiert.")

T="Funktionenfolgen & Potenzreihen"
c("Definition",T,r"Punktweise Konvergenz",r"$f_n:D\to\mathbb R$ konvergiert punktweise gegen $f$, wenn $f_n(x)\to f(x)$ für jedes $x\in D$.")
c("Definition",T,r"Gleichmäßige Konvergenz",r"$f_n\to f$ gleichmäßig auf $D$, wenn $\sup_{x\in D}|f_n(x)-f(x)|\to0$, d. h. $\forall\varepsilon\ \exists N\ \forall n\ge N\ \forall x\in D: |f_n(x)-f(x)|<\varepsilon$.",extra=r"$f_n(x)=x^n$ auf $[0,1]$ konvergiert punktweise, aber nicht gleichmäßig (die Grenzfunktion ist unstetig).")
c("Satz",T,r"",r"Die Grenzfunktion $f$ ist stetig.",front=r"Seien $f_n:D\to\mathbb R$ stetig und $f_n\to f$ gleichmäßig.")
c("Satz",T,r"Vertauschung von Limes und Integral",r"Konvergieren integrierbare $f_n\to f$ gleichmäßig auf $[a,b]$, so ist $f$ integrierbar und $\int_a^bf_n\to\int_a^bf$.")
c("Satz",T,r"Vertauschung von Limes und Ableitung",r"Sind $f_n$ stetig differenzierbar, konvergiert $(f_n)$ in einem Punkt und $(f_n')$ gleichmäßig, so konvergiert $f_n\to f$ gleichmäßig, $f$ ist differenzierbar und $f'=\lim f_n'$.")
c("Satz",T,r"Weierstraß-Kriterium (M-Test)",r"Ist $\|f_k\|_\infty\le M_k$ und $\sum M_k<\infty$, so konvergiert $\sum f_k$ absolut und gleichmäßig.")
c("Definition",T,r"Potenzreihe und Konvergenzradius",r"$\sum_{k=0}^\infty a_k(x-x_0)^k$ heißt Potenzreihe. Ihr Konvergenzradius ist $$R=\frac1{\limsup_{k\to\infty}\sqrt[k]{|a_k|}}\in[0,\infty]$$ (Cauchy-Hadamard). Für $|x-x_0|<R$ konvergiert sie absolut, für $|x-x_0|>R$ divergiert sie.")
c("Satz",T,r"",r"Sie konvergiert auf jedem $[x_0-r,x_0+r]$ mit $r<R$ gleichmäßig, ist dort beliebig oft differenzierbar, und man darf gliedweise differenzieren und integrieren (mit gleichem Radius $R$).",front=r"Sei $\sum a_k(x-x_0)^k$ eine Potenzreihe mit Konvergenzradius $R>0$.")
c("Satz",T,r"Identitätssatz für Potenzreihen",r"Stimmen zwei Potenzreihen um $x_0$ auf einer Menge überein, die $x_0$ als Häufungspunkt hat, so sind alle Koeffizienten gleich.")
c("Satz",T,r"Approximationssatz von Weierstraß",r"Zu jeder stetigen Funktion $f:[a,b]\to\mathbb R$ und jedem $\varepsilon>0$ gibt es ein Polynom $p$ mit $\sup_{[a,b]}|f-p|<\varepsilon$.")
